                p_17_p_1 = p_17.zero_add(beaver3_tuples[11].b);  // p[17]'_1, mask=b23
                p_18_p = p_18.zero_add(beaver3_tuples[11].c);  // p[18]', mask=c23
                p_19_p = p_19.zero_add(beaver3_tuples[12].a);  // p[19]', mask=a25
                p_19_p_1 = p_19.zero_add(beaver4_tuples[6].a);  // p[19]'_1, mask=a26
                p_20_p = p_20.zero_add(beaver4_tuples[6].b);  // p[20]', mask=b26
                // and_0: a0=triples[0].a, b0=triples[0].b, c0=triples[0].c, output mask=r116
                B3G_1_3_g1 = a_1_p.prepare_dot_and_assign(b_1_p, r116, triples[0].c);  // and_0
                // and3_2: a0=beaver3_tuples[0].a, b0=beaver3_tuples[0].b, c0=beaver3_tuples[0].c, output mask=r117
                B3G_1_3_t1 = p_1_p.prepare_dot3_and_assign(a_2_p, b_2_p, r117, beaver3_tuples[0]);  // and3_2
                // and4_4: a0=beaver4_tuples[0].a, b0=beaver4_tuples[0].b, c0=beaver4_tuples[0].c, d0=beaver4_tuples[0].d, output mask=r118
                B3G_1_3_t2 = p_1_p_1.prepare_dot4_and_assign(p_2_p, a_3_p, b_3_p, r118, beaver4_tuples[0]);  // and4_4
                B3G_1_3_s1 = B3G_1_3_g1 ^ B3G_1_3_t1;  // B3G_1_3_s1
                B3G_1_3_out = B3G_1_3_s1 ^ B3G_1_3_t2;  // B3G_1_3_out
