                // and3_8: a1=beaver3_tuples[1].a, b1=beaver3_tuples[1].b, c1=beaver3_tuples[1].c, output mask=a30
                B3P_1_3_out = p_1_p_2.prepare_and3_and_assign(p_2_p_1, p_3_p, beaver4_tuples[8].a, beaver3_tuples[1]);  // and3_8
                // and_9: a1=triples[1].a, b1=triples[1].b, c1=triples[1].c, output mask=r103
                B3G_4_6_g1 = a_4_p.prepare_dot_and_assign(b_4_p, r103, triples[1].c);  // and_9
